int[] zahlen = { 5, 3, 8, 1, 4 };
BubbleSort(zahlen);
Console.WriteLine(string.Join(" ", zahlen));
// Start:        5 3 8 1 4
// Durchgang 1:  3 5 1 4 8
// Durchgang 2:  3 1 4 5 8
// Durchgang 3:  1 3 4 5 8
// Durchgang 4:  kein Tausch → fertig

void BubbleSort(int[] a)
{
    int n = a.Length;
    for (int i = 0; i < n - 1; i++)
    {
        bool getauscht = false;
        for (int j = 0; j < n - 1 - i; j++)
        {
            if (a[j] > a[j + 1])
            {
                int temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
                getauscht = true;
            }
        }
        if (!getauscht) break;
    }
}

int[] zahlen = { 5, 3, 8, 1, 4 };
SelectionSort(zahlen);
Console.WriteLine(string.Join(" ", zahlen));
// i = 0: Min 1 → 1 | 3 8 5 4
// i = 1: Min 3 → 1 3 | 8 5 4
// i = 2: Min 4 → 1 3 4 | 5 8
// i = 3: Min 5 → 1 3 4 5 | 8

void SelectionSort(int[] a)
{
    int n = a.Length;
    for (int i = 0; i < n - 1; i++)
    {
        int minIndex = i;
        for (int j = i + 1; j < n; j++)
        {
            if (a[j] < a[minIndex])
            {
                minIndex = j;
            }
        }
        int temp = a[i];
        a[i] = a[minIndex];
        a[minIndex] = temp;
    }
}

int[] zahlen = { 5, 3, 8, 1, 4 };
InsertionSort(zahlen);
Console.WriteLine(string.Join(" ", zahlen));
// i = 1: 3 einfügen → 3 5 | 8 1 4
// i = 2: 8 einfügen → 3 5 8 | 1 4
// i = 3: 1 einfügen → 1 3 5 8 | 4
// i = 4: 4 einfügen → 1 3 4 5 8

void InsertionSort(int[] a)
{
    for (int i = 1; i < a.Length; i++)
    {
        int wert = a[i];
        int j = i - 1;
        while (j >= 0 && a[j] > wert)
        {
            a[j + 1] = a[j];  // nach rechts
            j--;
        }
        a[j + 1] = wert;
    }
}

